namespace CiJing {
public static class RevisitRules {
 public static bool Check(Stone[] cells,int which,out string reason){var notes=Enumerable.Range(0,8).Where(i=>!cells[i].Empty).ToArray();if(notes.Length!=2||notes.Any(i=>cells[i].rank!=1||cells[i].echo!=0)){reason="只用两枚短音，余处留白。";return false;}int a=notes[0],b=notes[1];if(which==0){if(cells[a].tone!=1||cells[b].tone!=0){reason="岸上宫先商后，水中须倒过来读。";return false;}if(b-a<2||b>6){reason="两声之间与曲尾，皆留静处看水影。";return false;}}else{if(cells[a].tone!=0||cells[b].tone!=1){reason="宫先问，商后答，仍是旧灯下的两声。";return false;}if(b-a!=3||b>6){reason="先听宫，整整候两拍空，再以商答；曲尾勿添声。";return false;}}reason="旧景中，原来还有这一句。";return true;}
}
public sealed class RevisitSlot:MonoBehaviour,IPointerClickHandler {public GameApp app;public int index;public void OnPointerClick(PointerEventData e){app.SelectRevisit(index);}}
public sealed partial class GameApp {
 Board revisitBoard;int revisitWhich,revisitSelected=-1,revisitToken;bool revisitPlaying,revisitOpen;Text revisitWords;Text[] revisitLabels;ScoreSceneView revisitView;RawImage revisitReward;
 bool RevisitUnlocked(int which){return which==0?(save.unlocked>=4||save.sceneDiscoveries.Any(s=>(s&1)!=0)):(save.unlocked>=7||save.finished);}
 void ShowRevisits(){if(modal)CloseModal();OpenModal("旧 景 余 音","新学的留白与回望，也可拿去读旧景。\n两处旧痕各藏一小句，读懂后收入此行留卷。","返回",CloseModal);for(int i=0;i<2;i++){int n=i;var button=Button(modal,(i==0?"溪亭 · 水痕回文":"旧灯 · 隔水候音")+((save.revisited&(1<<i))!=0?" · 已读":""),440,430+i*80,710,58,()=>OpenRevisit(n));button.interactable=RevisitUnlocked(i);}Label(modal,"水影初见，可回溪亭；西楼闻答，可再访旧灯。",435,590,735,35,19,accent);Button(modal,"此行留卷",1040,650,200,58,ShowKeepsake);}
 void OpenRevisit(int which){if(!RevisitUnlocked(which))return;if(modal)CloseModal();OpenModal(which==0?"溪 亭 · 水 痕 回 文":"旧 灯 · 隔 水 候 音","","返回旧景册",()=>{CloseModal();ShowRevisits();});revisitOpen=true;revisitWhich=which;revisitSelected=-1;revisitToken++;revisitBoard=new Board();revisitBoard.cells[8]=new Stone(0);revisitBoard.cells[9]=new Stone(1);revisitReward=null;revisitLabels=new Text[10];var stage=Rect("Old scene remembered",modal,420,285,750,145);var raw=Rect("Old river",stage,0,-20,750,190).gameObject.AddComponent<RawImage>();raw.texture=Resources.Load<Texture2D>("Painting/stage1");raw.uvRect=new Rect(0,.2f,1,.45f);raw.raycastTarget=false;raw.color=new Color(1,1,1,.6f);revisitView=Rect("Old water with new meaning",stage,0,0,750,145).gameObject.AddComponent<ScoreSceneView>();revisitView.raycastTarget=false;revisitView.Set(SceneScore.Begin(which==0?0:2),true);AddGuideReflection(stage,revisitView,530,100);
  var objectArt=Rect("Old witness",stage,30,10,95,115).gameObject.AddComponent<RawImage>();objectArt.texture=Resources.Load<Texture2D>("PropsInk/"+(which==0?"waterstone":"boatlantern"));objectArt.raycastTarget=false;Label(modal,which==0?"岸上旧痕：宫 · 商　　水影须待声歇才显。":"旧灯问宫，远岸答商；两拍静处，才能听清。",435,435,740,44,22);
  for(int i=0;i<10;i++){int cell=i;float x=i<8?435+i*90:435+(i-8)*90,y=i<8?493:578;var image=Panel(modal,x,y,64,64,new Color(.7f,.64f,.48f,.08f));image.sprite=disc;image.raycastTarget=true;var input=image.gameObject.AddComponent<RevisitSlot>();input.app=this;input.index=cell;revisitLabels[i]=Label(image.transform,"",0,0,64,64,22,ink,TextAnchor.MiddleCenter);if(i<8)Label(modal,"一二三四五六七八"[i].ToString(),x+18,y-20,30,22,16,accent,TextAnchor.MiddleCenter);}
  revisitWords=Label(modal,"点行囊短音，再点上方空位。",650,568,545,34,20,accent);Button(modal,"听旧声",675,610,220,36,PlayRevisit,true);Button(modal,"重置小卷",935,610,240,36,()=>OpenRevisit(revisitWhich));UpdateRevisitSlots();}
 public void SelectRevisit(int i){if(!revisitOpen||revisitPlaying||i<0||i>=10)return;if(revisitSelected<0){if(revisitBoard.cells[i].Empty)return;revisitSelected=i;Sound(revisitBoard.cells[i]);}else if(revisitSelected==i)revisitSelected=-1;else{if(revisitBoard.Move(revisitSelected,i))revisitSelected=-1;else revisitSelected=revisitBoard.cells[i].Empty?-1:i;}UpdateRevisitSlots();}
 void UpdateRevisitSlots(){if(revisitLabels==null)return;for(int i=0;i<10;i++)if(revisitLabels[i]){var s=revisitBoard.cells[i];revisitLabels[i].text=s.Empty?"·":s.ToString();revisitLabels[i].fontSize=19;revisitLabels[i].color=revisitSelected==i?red:ink;}}
 void PlayRevisit(){if(!revisitOpen||revisitPlaying)return;revisitPlaying=true;revisitSelected=-1;StartCoroutine(RevisitPerformance(revisitToken));}
 IEnumerator RevisitPerformance(int token){var state=SceneScore.Begin(revisitWhich==0?0:2);for(int i=0;i<8;i++){if(!revisitOpen||token!=revisitToken)yield break;state=SceneScore.Step(state,revisitBoard.cells[i],revisitWhich==0?0:2);revisitView.Set(state);music.Environment(state);Sound(revisitBoard.cells[i]);revisitWords.text="第 "+(i+1)+" 拍 · "+state.caption;yield return new WaitForSeconds(.7f);}if(!revisitOpen||token!=revisitToken)yield break;revisitPlaying=false;string why;if(RevisitRules.Check(revisitBoard.cells,revisitWhich,out why)){save.revisited|=1<<revisitWhich;Persist();music.Cadence(revisitWhich==0?0:2,false);revisitWords.text=revisitWhich==0?"水影倒读：归时，留一盏灯。":"候过两拍，远岸答：灯还在。";if(!revisitReward){revisitReward=Rect("An old folded answer",modal,1010,320,130,95).gameObject.AddComponent<RawImage>();revisitReward.texture=Resources.Load<Texture2D>("PropsInk/petalletter");revisitReward.raycastTarget=false;AddRelicTrace(revisitReward.transform,2,130,95);}}else revisitWords.text=why;}
 void CloseRevisit(){revisitToken++;revisitOpen=revisitPlaying=false;revisitView=null;revisitWords=null;revisitLabels=null;revisitBoard=null;Silence();music.Environment(moment);}
}
